function strip(s) {
  return String(s || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim().slice(0, 3500);
}
function eligible(loc) {
  var t = String(loc || '').toLowerCase().trim();
  if (!t) return true;
  return /worldwide|anywhere|global|nigeria|africa|emea|international/.test(t);
}
var maxAgeMs = 7 * 24 * 3600 * 1000;
var now = Date.now();
var out = [];
for (var it of $input.all()) {
  var j = it.json || {};
  if (Array.isArray(j.jobs)) {
    for (var job of j.jobs) {
      if (job.company_name !== undefined) {
        var ts = Date.parse(job.publication_date + 'Z');
        if (!eligible(job.candidate_required_location)) continue;
        out.push({ id: 'remotive:' + job.id, source: 'Remotive', title: job.title, company: job.company_name, url: job.url, location: job.candidate_required_location || 'Worldwide', description: strip(job.description), closing: '', ts: ts });
      } else {
        var restr = Array.isArray(job.locationRestrictions) ? job.locationRestrictions : [];
        if (restr.length && !eligible(restr.join(' '))) continue;
        var closing = job.expiryDate ? new Date(job.expiryDate * 1000).toISOString().slice(0, 10) : '';
        out.push({ id: 'himalayas:' + (job.guid || job.applicationLink), source: 'Himalayas', title: job.title, company: job.companyName, url: job.applicationLink || job.guid, location: restr.length ? restr.join(', ') : 'Worldwide', description: strip(job.description || job.excerpt), closing: closing, ts: job.pubDate ? job.pubDate * 1000 : now });
      }
    }
  } else if (j.position) {
    if (!eligible(j.location)) continue;
    out.push({ id: 'remoteok:' + j.id, source: 'RemoteOK', title: j.position, company: j.company, url: j.apply_url || j.url, location: j.location || 'Worldwide', description: strip(j.description), closing: '', ts: Date.parse(j.date) });
  }
}
out = out.filter(function (o) { return o.title && o.url && (!o.ts || now - o.ts < maxAgeMs); });
out.sort(function (a, b) { return (b.ts || 0) - (a.ts || 0); });
return out.map(function (o) { return { json: o }; });

var posted = {};
var today = new Date().toLocaleDateString('en-CA', { timeZone: 'Africa/Lagos' });
var month = today.slice(0, 7);
var perDay = 0, perMonth = 0;
for (var p of $input.all()) {
  var r = p.json || {};
  if (!r.job_id) continue;
  posted[r.job_id] = true;
  var d = String(r.posted_on || '');
  if (d === today) perDay++;
  if (d.slice(0, 7) === month) perMonth++;
}
var remaining = Math.min(2 - perDay, 50 - perMonth);
var out = [];
if (remaining <= 0) return out;
for (var it of $('Normalize and Filter Jobs').all()) {
  if (!posted[it.json.id]) out.push({ json: it.json });
}
out = out.slice(0, remaining);
return out;

