var jobs = $('Limit Jobs').all();
var sd = $getWorkflowStaticData('global');
var out = [];
var all = $input.all();
for (var i = 0; i < all.length; i++) {
  var j = all[i].json;
  var job = jobs[i].json;
  var text = '';
  if (j.content && j.content.parts && j.content.parts[0]) text = j.content.parts[0].text;
  else if (j.candidates && j.candidates[0]) text = j.candidates[0].content.parts[0].text;
  else text = j.output || j.text || '';
  text = String(text).replace(/```json|```/g, '').trim();
  var parsed = {};
  try { parsed = JSON.parse(text); } catch (e) { parsed = {}; }
  var reqs = Array.isArray(parsed.requirements) ? parsed.requirements.slice(0, 5) : [];
  if (!reqs.length) reqs = ['See the full job description at the application link'];
  var closing = job.closing || (parsed.closing_date && parsed.closing_date !== 'null' ? parsed.closing_date : '');
  var closingText = closing || 'Not stated - apply early';
  var count = sd.postCount || 0;
  var templateIndex = Math.floor(count / 3) % 2;
  sd.postCount = count + 1;
  var caption = 'JOB: ' + job.title + ' (' + job.company + ')\n\n' +
    'Essential Requirements:\n' + reqs.map(function (r) { return '- ' + r; }).join('\n') + '\n\n' +
    'Open until: ' + closingText + '\n\n' +
    'Apply here: [[LINK]]\n\n' +
    'Remote role - open to applicants in Nigeria (' + job.location + ')\n' +
    '#remotejobs #nigeriajobs #remotework #hiring #jobsinnigeria';
  out.push({ json: { jobId: job.id, url: job.url, urlIsLong: String(job.url).length > 40, captionBase: caption, templateIndex: templateIndex, title: job.title, company: job.company, reqs: reqs, closingText: closingText } });
}
return out;

var d = $('Parse Details').item.json;
var link = $json.applyLink || d.url;
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
var O = '#556B2F', W = '#FFFFFF';
var th = d.templateIndex === 1
  ? { hb: W, hf: O, bb: O, bf: W, fb: W, ff: O, acc: O }
  : { hb: O, hf: W, bb: W, bf: O, fb: O, ff: W, acc: O };
var reqs = (d.reqs || []).slice(0, 4).map(function (r) { return '<li>' + esc(r) + '</li>'; }).join('');
var titleSize = String(d.title || '').length > 60 ? 48 : 58;
var css = 'body{margin:0;font-family:Montserrat,Arial,sans-serif;}' +
  '.card{width:1080px;height:1080px;display:flex;flex-direction:column;overflow:hidden;border:10px solid ' + O + ';box-sizing:border-box;}' +
  '.head{background:' + th.hb + ';color:' + th.hf + ';padding:56px 64px 44px 64px;}' +
  '.tag{font-size:26px;font-weight:700;letter-spacing:3px;opacity:0.9;}' +
  '.title{font-size:' + titleSize + 'px;font-weight:800;line-height:1.1;margin-top:22px;}' +
  '.company{font-size:34px;font-weight:600;margin-top:14px;opacity:0.95;}' +
  '.body{flex:1;background:' + th.bb + ';color:' + th.bf + ';padding:44px 64px;}' +
  '.label{font-size:26px;font-weight:800;letter-spacing:2px;text-transform:uppercase;}' +
  'ul{margin:16px 0 0 0;padding-left:36px;font-size:29px;line-height:1.35;}' +
  'li{margin-bottom:12px;}' +
  '.foot{background:' + th.fb + ';color:' + th.ff + ';padding:34px 64px;}' +
  '.open{font-size:40px;font-weight:800;}' +
  '.link{font-size:26px;margin-top:10px;word-break:break-all;opacity:0.95;}';
var html = '<div class="card"><div class="head"><div class="tag">REMOTE JOB - OPEN TO NIGERIANS</div>' +
  '<div class="title">' + esc(d.title) + '</div><div class="company">' + esc(d.company) + '</div></div>' +
  '<div class="body"><div class="label">Essential requirements</div><ul>' + reqs + '</ul></div>' +
  '<div class="foot"><div class="open">Open until: ' + esc(d.closingText) + '</div>' +
  '<div class="link">Apply: ' + esc(link) + '</div></div></div>';
return { json: { html: html, css: css } };
